class Solution:

	def solve(self, arr, i, dp):
		if arr[i] == -1:
			return 1
		if dp[i] != -1:
			return dp[i]
		return self.solve(arr, arr[i], dp) + 1

	def findHeight(self, N, arr):
		dp = [-1] * N
		ans = 0
		for i in range(N):
			ans = max(ans, self.solve(arr, i, dp))
		return ans
